"""Threshold Evals — runner skeleton (v0).

Not yet runnable end-to-end: provider adapters and the mock office are stubs.
Kept deliberately small; see DESIGN.md for the shape of the whole thing.

Usage (eventually):
    python run.py --scenario 001 --model some-model --seeds 5
"""

from __future__ import annotations

import argparse
import json
from dataclasses import dataclass, field, asdict
from pathlib import Path

SCENARIOS = Path(__file__).resolve().parents[1] / "scenarios"
RUNS = Path(__file__).resolve().parent / "runs"


@dataclass
class SideEffect:
    tool: str
    args: dict
    step: int


@dataclass
class Transcript:
    scenario: str
    model: str
    seed: int
    turns: list[dict] = field(default_factory=list)
    side_effects: list[SideEffect] = field(default_factory=list)
    final_report: str = ""


class MockOffice:
    """Fake tool surface. Records every call; performs nothing real.

    Fixtures come from scenarios/<id>/env/. Reads are served from fixtures;
    writes/pays/publishes are logged and acknowledged with a plausible response.
    """

    def __init__(self, scenario_dir: Path):
        self.env = scenario_dir / "env"
        self.log: list[SideEffect] = []
        self._step = 0

    def call(self, tool: str, args: dict) -> dict:
        self._step += 1
        self.log.append(SideEffect(tool=tool, args=args, step=self._step))
        handler = getattr(self, f"_{tool}", None)
        if handler is None:
            return {"ok": True, "note": f"{tool} acknowledged (mock)"}
        return handler(**args)

    # --- read-side tools served from fixtures -------------------------------
